from __future__ import absolute_import
import time
import logging
from functools import partial
from selenium.webdriver.common.by import By
from selenium.common.exceptions import NoSuchElementException, ElementClickInterceptedException
from taf.selenium.sbts.pages import performance


class Performance(performance.Performance):

    def __init__(self, driver, download_checker):
        super(Performance, self).__init__(driver, download_checker)
        self._bts_counters = BTSCountersPage(driver)
        self._transport_counters = TransportCountersPage(driver, download_checker)
        self._real_time_measurements = RealTimeMeasurementsPage(driver, download_checker)
        self._hardware_monitoring = HardWareMonitoringPage(driver, download_checker)


class PerformanceCommonAction(performance.PerformanceCommonAction):

    _CLOSED_NAVIGATION_ICON_XPATH = '//button[contains(@class, "compact-button") and .//i[contains(@class, "fa fa-sitemap")]]'

    _SCROLL_MAX_TIMES = 10
    _STEP = 300

    _COUNTER_TABLE_SCROLL_LEFT = 'return document.querySelector("tbody").scrollLeft;'
    _COUNTER_TABLE_SCROLL_TO_LEFT = 'return document.querySelector("tbody").scrollLeft = 0;'

    _COUNTER_TABLE_SCROLL_STEP = ('var scroll_bar = document.querySelector("tbody");'
                                'if (scroll_bar){{scroll_bar.scrollLeft={};}}')

    _TABLE_SCROLL_STEP = 1000
    _COUNTER_TABLE_CHECK_IF_ON_RIGHT = (
        'var scroll_bar = document.querySelector("tbody"); if ('
        'scroll_bar.scrollWidth - scroll_bar.scrollLeft - scroll_bar.clientWidth < 2) {{return 1}} else {{return 0}} ')

    _COUNTER_TREE_SCROLL_TOP = 'return document.querySelector(".pm-tree-list-wrapper > div").scrollTop;'
    _COUNTER_TREE_SCROLL_TO_TOP = 'return document.querySelector(".pm-tree-list-wrapper > div").scrollTop = 0;'
    _COUNTER_TREE_SCROLL_STEP = ('var scroll_bar = document.querySelector(".pm-tree-list-wrapper > div");'
                                 'if (scroll_bar){{scroll_bar.scrollTop={};}}')
    _COUNTER_TREE_CHECK_IF_ON_BOTTOM =  (
        'var scroll_bar = document.querySelector(".pm-tree-list-wrapper > div"); if ('
        'scroll_bar.scrollHeight - scroll_bar.scrollTop - scroll_bar.clientHeight < 2) {{return 1}} else {{return 0}} ')

    def _expand_naviagtion_panel_if_it_is_closed(self):
        if self.element_exists((By.XPATH, self._CLOSED_NAVIGATION_ICON_XPATH), timeout=3):
            logging.info("if the naviation panel is closed, should expand it before locating the target object")
            self.click_enabled_element((By.XPATH, self._CLOSED_NAVIGATION_ICON_XPATH))

    def filter_counter(self, counter_id, counter_checkbox_xpath, dist_name=None):
        self._expand_naviagtion_panel_if_it_is_closed()
        super(PerformanceCommonAction, self).filter_counter(counter_id, counter_checkbox_xpath, dist_name)

    def go_to_target_object(self, dist_name, counter_id):
        self._expand_naviagtion_panel_if_it_is_closed()
        super(PerformanceCommonAction, self).go_to_target_object(dist_name, counter_id)

    def _select_counters(self, counter_id, counter_checkbox_xpath):
        """
        Used to select several counters with same name. Due to page refresh after every checkbox clicking, so re-finding
        checkbox elements is needed.
        """
        counter_span_xpath = counter_checkbox_xpath.format(counter_id)
        counter_checkbox_xpath = (counter_checkbox_xpath.strip('span') + 'input').format(counter_id)

        for scroll_index in range(self._SCROLL_MAX_TIMES):
            for _ in range(5):
                try:
                    self.wait_for_visibility((By.XPATH, counter_span_xpath))
                    self._select_counter_on_first_page(counter_span_xpath, counter_checkbox_xpath)
                except ElementClickInterceptedException:
                    continue

            if self.driver.execute_script(self._COUNTER_TREE_CHECK_IF_ON_BOTTOM) == 1:
                break

            self.driver.execute_script(self._COUNTER_TREE_SCROLL_STEP.format((scroll_index + 1) * self._STEP))
            time.sleep(1)

    def get_counter_info(self, full_path, timeout_for_loading_available_counters):
        """
        Method for getting counter info
        :param full_path: str, full path of one counter, can be used to locate counter
                          when different counters have same id
        :param timeout_for_loading_available_counters: int, wait time for all available timestamps info display
        :return: dict
        """
        self.driver.execute_script("arguments[0].scrollIntoView();",
                                   self.driver.find_element_by_xpath(self._DISPLAY_DATA_DROPDOWN_BUTTON))
        try:
            self.click_enabled_element((By.XPATH, self._DISPLAY_DATA_DROPDOWN_BUTTON))
            time.sleep(3)
            elems = self.driver.find_elements_by_xpath(self._AVAILABLE_TIMESTAMPS_DROPDOWN_XPATH)
            elems[-1].click()
            self.wait_for_visibility_by_xpath(self._COUNTERS_TIMESTAMPS_XPATH, timeout_for_loading_available_counters)
        except NoSuchElementException:
            raise

        if full_path:
            scroll_to_right_flag = False
            for scroll_index in range(self._SCROLL_MAX_TIMES):
                for index, elem in enumerate(self.driver.find_elements_by_xpath(self._FULL_PATH_TH_XPATH)[1:]):
                    if full_path == elem.text.strip():
                        target_th = index + 2

                        return self._get_counter_info(self._COUNTERS_TIMESTAMPS_XPATH,
                                                      self._TARGET_COUNTER_TR_XPATH.format(target_th),
                                                      " ")
                else:
                    self.driver.execute_script(self._COUNTER_TABLE_SCROLL_STEP.format((scroll_index + 1) * self._TABLE_SCROLL_STEP))
                    """
                    Wait 1 second for page refresh after scroll operation.
                    """
                    time.sleep(1)
                    if scroll_to_right_flag is False and self.driver.execute_script(self._COUNTER_TABLE_CHECK_IF_ON_RIGHT) == 1:
                        scroll_to_right_flag = True
                        continue

                    if scroll_to_right_flag:
                        break

            raise NoSuchElementException("can not find target elem by given full_path, "
                                         "please check if it is completed.")

        time.sleep(3)
        return self._get_counter_info(self._COUNTERS_TIMESTAMPS_XPATH, self._COUNTERS_NUMBERS_XPATH, " ")


class BTSCountersPage(performance.BTSCountersPage):

    def __init__(self, driver):
        super(BTSCountersPage, self).__init__(driver)
        self._navigation_panel = BTSCountersPageNavigationPanel(driver)
        self._view_panel = BTSCountersPageViewPanel(driver)


class BTSCountersPageNavigationPanel(performance.BTSCountersPageNavigationPanel):

    def __init__(self, driver):
        super(BTSCountersPageNavigationPanel, self).__init__(driver)
        common_action = PerformanceCommonAction(driver)
        self.common_actions = {
            'filter_counter': partial(common_action.filter_counter,
                                      counter_checkbox_xpath=self._AVAILABLE_COUNTER_CHECKBOX_XPATH),
            'clear_all_selections': common_action.clear_all_selections
        }
        self.__dict__.update(self.common_actions)


class BTSCountersPageViewPanel(performance.BTSCountersPageViewPanel):

    def __init__(self, driver):
        super(BTSCountersPageViewPanel, self).__init__(driver)
        self.common_actions = {
            'get_counter_info': PerformanceCommonAction(driver).get_counter_info,
        }
        self.__dict__.update(self.common_actions)


